    private static FarmSave XDocumentSaveCopy(FarmSave state)
    {
        using(var reader=new StringReader(FarmPracticeTests.Xml(state)))return (FarmSave)new System.Xml.Serialization.XmlSerializer(typeof(FarmSave)).Deserialize(reader);
